syntax:
if (condition)
{
    statementA;     // runs when the condition is TRUE
}
else                // no condition and no semicolon after else
{
    statementB;     // runs when the condition is FALSE
}
nextStatement;      // runs after either block

// One statement each: braces optional
if (condition)
    statementA;
else
    statementB;

sample.code:
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Enter a number: ";
    cin >> n;
    if (n % 2 == 0)
        cout << n << " is even." << endl;
    else
        cout << n << " is odd." << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int marks;
    cout << "Enter marks: ";
    cin >> marks;
    if (marks >= 50) {
        cout << "Pass" << endl;
    } else {
        cout << "Fail" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int age;
    cout << "Enter age: ";
    cin >> age;
    if (age >= 18) {
        cout << "You can vote." << endl;
    } else {
        cout << "You cannot vote yet." << endl;
        int wait = 18 - age;
        cout << "Years to wait: " << wait << endl;
    }
    return 0;
}

